-- plan sha256 f3aec835dc05dd5cd84c285976653dc0d7edfd5025376253b5a2530ef90312e4
-- Generated by scripts/remediation/mechanical/apply.py - do not edit by hand.
-- 196 row(s) over 98 site(s); scope source_id = 'ancient_nerds';
-- run stamp '2026-09-23_mechanical-scope-e4-rollback'; journal test id 'E4/scope-status'.
-- Every UPDATE is conditioned on the old value the plan names; every change is journalled
-- in the same transaction, so the audit trail cannot disagree with the data.
\set ON_ERROR_STOP on
BEGIN;

-- The server bounds this transaction itself: a lock wait or a runaway statement raises
-- here, psql stops the script (exit 3) and nothing is kept. A client that gives up does
-- not stop the server - psql has the whole script on its stdin.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE TEMP TABLE _scope_plan (
    site_id     UUID NOT NULL,
    column_name TEXT NOT NULL,
    old_value   TEXT,
    new_value   TEXT,
    change_key  TEXT NOT NULL,
    reason      TEXT NOT NULL,
    premise     TEXT NOT NULL,
    evidence    JSONB NOT NULL,
    PRIMARY KEY (site_id, column_name)
) ON COMMIT DROP;


DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 196;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _scope_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _scope_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'scope_status' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL
                WHEN 'scope_reason' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _scope_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.old_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _scope_plan p
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN p.old_value NOT IN ('in_scope', 'retired', 'pending')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _scope_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (concat_ws(' | ', coalesce(u.period_start::text, 'NULL'), coalesce(u.period_end::text, 'NULL'), u.lat::text, u.lon::text, coalesce(u.site_type, 'NULL'), u.name)) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _scope_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'E4/scope-status', '2026-09-23_mechanical-scope-e4-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'E4 scope decision: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _scope_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _scope_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-09-23_mechanical-scope-e4-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-23_mechanical-scope-e4-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('scope_status', 'scope_reason'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'E4 scope decision: this run stamp journalled % row(s) outside unified_sites.(scope_status, scope_reason)', bad;
    END IF;

    RAISE NOTICE 'E4 scope decision: % of % planned cell(s) changed and journalled over 98 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-23_mechanical-scope-e4-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'E4/scope-status'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-09-23_mechanical-scope-e4-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('scope_status', 'scope_reason')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'scope_status' THEN u.scope_status IS NOT DISTINCT FROM l.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows outside the E3 window with no scope decision', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND (lon IS NOT NULL AND (CASE WHEN period_end IS NOT NULL AND period_end <> 0 THEN period_end ELSE period_start END) > (CASE WHEN lon BETWEEN -170 AND -30 THEN 1500 ELSE 500 END)) AND scope_status IS NULL
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
